// Install: npm install express
const express = require('express');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json());

// GET route — returns a greeting
app.get('/', (req, res) => {
  res.json({ message: 'Hello from Express!' });
});

// GET route with a URL parameter
app.get('/users/:id', (req, res) => {
  res.json({ userId: req.params.id });
});

// POST route — receives JSON data
app.post('/users', (req, res) => {
  const { name, email } = req.body;
  res.status(201).json({ id: 1, name, email });
});

// Start the server
app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});

// Custom logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.url}`);
  next(); // pass control to the next middleware
});

// Authentication middleware
function requireAuth(req, res, next) {
  const token = req.headers.authorization;
  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }
  // Verify token...
  req.user = { id: 1, name: 'Ada' }; // attach user to request
  next();
}

// Use middleware on specific routes only
app.get('/profile', requireAuth, (req, res) => {
  res.json({ user: req.user });
});

// Error-handling middleware (4 arguments!)
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// routes/users.js — modular router
const express = require('express');
const router = express.Router();

// In-memory data (replace with a database in production)
let users = [{ id: 1, name: 'Ada', email: 'ada@example.com' }];

// GET /users — list all users
router.get('/', (req, res) => {
  res.json(users);
});

// GET /users/:id — get one user
router.get('/:id', (req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json(user);
});

// POST /users — create a user
router.post('/', (req, res) => {
  const { name, email } = req.body;
  const user = { id: users.length + 1, name, email };
  users.push(user);
  res.status(201).json(user);
});

// PUT /users/:id — update a user
router.put('/:id', (req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));
  if (!user) return res.status(404).json({ error: 'User not found' });
  Object.assign(user, req.body);
  res.json(user);
});

// DELETE /users/:id — delete a user
router.delete('/:id', (req, res) => {
  const index = users.findIndex(u => u.id === parseInt(req.params.id));
  if (index === -1) return res.status(404).json({ error: 'User not found' });
  users.splice(index, 1);
  res.status(204).send();
});

module.exports = router;

// app.js — mount the router
const usersRouter = require('./routes/users');
app.use('/users', usersRouter);

// Validation with zod
const { z } = require('zod');

// Define a schema
const createUserSchema = z.object({
  name: z.string().min(1, 'Name is required').max(100),
  email: z.string().email('Invalid email'),
  age: z.number().int().min(0).max(150).optional(),
});

// Validation middleware
function validate(schema) {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({
        error: 'Validation failed',
        details: result.error.issues,
      });
    }
    req.body = result.data; // use the validated/transformed data
    next();
  };
}

// Use it
app.post('/users', validate(createUserSchema), (req, res) => {
  // req.body is guaranteed to match the schema
  res.status(201).json({ user: req.body });
});

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
  }
}

// Global error handler (must be LAST middleware)
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  const isDev = process.env.NODE_ENV === 'development';
  res.status(statusCode).json({
    error: err.message,
    ...(isDev && { stack: err.stack }),
  });
});

// Production Express setup
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const compression = require('compression');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// Trust proxy (needed when behind a reverse proxy like nginx/load balancer)
app.set('trust proxy', 1);

// Security middleware
app.use(helmet()); // security headers
app.use(cors({ origin: process.env.CORS_ORIGIN })); // restrict origins

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // max 100 requests per window per IP
  message: 'Too many requests from this IP',
});
app.use('/api/', limiter);

// Performance
app.use(compression()); // gzip responses

// Logging
app.use(morgan('combined'));

// Body parsing
app.use(express.json({ limit: '10kb' })); // limit body size

// Routes
app.use('/api/users', require('./routes/users'));

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
